  const cloud = (cx, cy, s) => `M${R(cx - s)},${R(cy + s * 0.3)} a${R(s * 0.45)},${R(s * 0.45)} 0 0,1 ${R(s * 0.55)},${R(-s * 0.5)} a${R(s * 0.5)},${R(s * 0.5)} 0 0,1 ${R(s * 0.9)},${R(-s * 0.1)} a${R(s * 0.45)},${R(s * 0.45)} 0 0,1 ${R(s * 0.55)},${R(s * 0.6)} Z`;
