  const pine = (cx, baseY, w, h) => [tri(cx, baseY - h * 0.5, w, h * 0.5), tri(cx, baseY - h * 0.25, w * 0.85, h * 0.5), tri(cx, baseY, w * 0.7, h * 0.5), rect(cx - w * 0.07, baseY, w * 0.14, h * 0.18)];
