  const flower = (cx, cy, r, n = 5, stemTo) => { const ps = []; for (let i = 0; i < n; i++) { const a = -Math.PI / 2 + i * 2 * Math.PI / n; ps.push(C(cx + Math.cos(a) * r * 1.5, cy + Math.sin(a) * r * 1.5, r * 0.8)); } ps.push(C(cx, cy, r * 0.7)); if (stemTo) ps.push(L(cx, cy + r * 1.8, cx, stemTo), B(cx, cy + r * 3, cx - r * 2, cy + r * 2.6, cx - r * 2.4, cy + r * 4, cx, cy + r * 3.2)); return ps; };
